mat2 rot2d(float angle){
  float s = sin(angle);
  float c = cos(angle);
  return mat2(c,-s, s, c);
}

float line_segment(in vec2 p, in vec2 a, in vec2 b) {
	vec2 ba = b - a;
	vec2 pa = p - a;
	float h = clamp(dot(pa, ba) / dot(ba, ba), 0., 1.);
	return length(pa - h * ba);
}

vec3 map(in vec2 p){
    if (abs(p.y+5.0) > 6.0 && abs(p.x-10.0) < 3.0 && p.y < 5.0 || abs(abs(p.y - 5.0)-1.0) < 1.0 && abs(p.x+8.0) > 5.0 || p.y > 10.0){
        return vec3(0.0);
    }
    return vec3(1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord *2.0 - iResolution.xy) / iResolution.y;
    vec2 tuv = (fragCoord *2.0 - iResolution.xy) / iResolution.y;
    vec2 m = (iMouse.xy *2.0 - iResolution.xy) / iResolution.y;

    m *= 20.0;
    uv *= 20.0;

    uv += m;

    vec3 col = vec3(1.0);

    float dis = 1.0;
    vec2 d = vec2(sin(iTime),cos(iTime));

    vec2 r = uv;

    float dd = atan(((r-m).x),((r-m).y));
    d = vec2(sin(dd)*-1.0,cos(dd)*-1.0);
    for( float i = 0.0; i < 80.0; i++){

    dd = atan(((r-m).x),((r-m).y));
    d = vec2(sin(dd)*-1.0,cos(dd)*-1.0);


    float mx = abs(d.x);
    mx = (1.0-mod(r.x,1.0))/(d.x);
    if (d.x < 0.0){
            mx = (mod(r.x,1.0))/(d.x)*-1.0;
    }

    float my = abs(d.y);
    if (min(mx,my) == my){
        my = (1.0-mod(r.y,1.0))/(d.y);
        if (d.y < 0.0){
            my = (mod(r.y,1.0))/(d.y)*-1.0;
        }
    }


    if (min(mx,my) == mx){
        dis = (1.0-mod(r.x,1.0))/(d.x);
        if (d.x < 0.0){
            dis = (mod(r.x,1.0))/(d.x)*-1.0;
        }
    }

    if (min(mx,my) == my){
        dis = (1.0-mod(r.y,1.0))/(d.y);
        if (d.y < 0.0){
            dis = (mod(r.y,1.0))/(d.y)*-1.0;
        }
    }


    if (map(r).x == 0.0){
        col -= vec3(0.4,0.3,0.2);
        if (map(uv).x == 0.0){
         col += vec3(0.1);
        }
    } else if(length(col)<0.9){
        col -= vec3(0.4);
        break;
    }

    r = r + (d*(dis+0.01));

    }


    // Output to screen
    fragColor = vec4(col,1.0);
}
